/**
 * How Oribe paulownia (`oribe-kiri`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/oribe-kiri";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Three heavily veined leaves spread under three spikes of round-lobed flowers. The middle spike has seven flowers and each side has five.","ja":"葉脈を太く抜いた葉を三枚広げ、その上に丸い裂片をもつ花穂を三本立てます。中央には花を七つ、左右には五つずつ置きます。"};

export default construction;
export { construction, description };
